package dev.skypilot.launcher.ui;

import dev.skypilot.launcher.Instance;
import dev.skypilot.launcher.GameWatcher;
import dev.skypilot.mod.core.*;
import javax.swing.*;
import java.awt.*;
import java.awt.datatransfer.StringSelection;
import java.awt.event.ActionEvent;
import java.util.concurrent.ThreadLocalRandom;

/** Local tools and a small arcade, without a backend or account requirement. */
final class DeskPage {
    private final Ctx c;
    private final JPanel root=Ui.page();
    private static final FocusTimer FOCUS=new FocusTimer();
    private final TileGame game=new TileGame(ThreadLocalRandom.current());
    private final JLabel clock=Ui.label("25:00",48,Font.BOLD,Theme.TEXT),score=Ui.title("");
    private final JPanel board=new JPanel(new GridLayout(4,4,8,8));
    private final JLabel[] tiles=new JLabel[16];
    private final javax.swing.Timer heartbeat;
    private Runnable refreshTasks=()->{};
    DeskPage(Ctx c){
        this.c=c;root.add(Ui.header(c.t("Your tool desk","ツールデスク"),c.t("A little focus. A little fun. Everything stays on your device.","集中も、ちょっとした遊びも。データは自分の端末に保存。")),BorderLayout.NORTH);
        JTabbedPane tabs=new JTabbedPane();tabs.setBorder(BorderFactory.createEmptyBorder(20,0,0,0));
        tabs.addTab(c.t("Focus","集中"),focus());tabs.addTab(c.t("Notebook","メモ"),notes());tabs.addTab(c.t("Calculator","電卓"),calculator());tabs.addTab(c.t("Random picker","抽選"),random());tabs.addTab(c.t("Tasks","ToDo"),tasks());tabs.addTab("2048",arcade());root.add(tabs,BorderLayout.CENTER);tabs.addChangeListener(e->{if(tabs.getSelectedIndex()==4)refreshTasks.run();});
        heartbeat=new javax.swing.Timer(500,e->{clock.setText(FOCUS.display(now()));if(FOCUS.finished(now()))c.ok(c.t("Focus complete","集中タイマー終了"),c.t("Time for a short break.","短い休憩を取りましょう。"));});
        root.addHierarchyListener(e->{if(root.isDisplayable())heartbeat.start();else heartbeat.stop();});
    }
    private static long now(){return System.nanoTime()/1_000_000;}
    private JPanel panel(){JPanel p=new JPanel();p.setOpaque(false);p.setBorder(BorderFactory.createEmptyBorder(24,24,24,24));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));return p;}
    private boolean persist(java.util.function.Consumer<SkyPilotConfig> edit){
        if(GameWatcher.check(c.settings.instance(),0).state()==GameWatcher.State.RUNNING){c.fail(c.t("Close the game first","ゲームを終了してください"),new IllegalStateException(c.t("Preventing conflicting configuration changes.","ゲーム内と設定が競合するため、保存できません。")));return false;}
        try{var cfg=Instance.config(c.settings.instance());edit.accept(cfg);Instance.saveConfig(c.settings.instance(),cfg);c.ok(c.t("Saved","保存しました"),"");return true;}catch(Exception ex){c.fail(c.t("Could not save","保存できませんでした"),ex);return false;}
    }
    private JPanel focus(){var p=panel();p.add(Ui.title(c.t("Make time for your next goal","次の目標に集中しよう")));p.add(Box.createVerticalStrut(24));p.add(clock);p.add(Box.createVerticalStrut(20));JSpinner minutes=new JSpinner(new SpinnerNumberModel(25,1,180,5));minutes.setMaximumSize(new Dimension(180,36));p.add(minutes);JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.setOpaque(false);button(actions,c.t("Start","開始"),()->{try{minutes.commitEdit();FOCUS.start((Integer)minutes.getValue(),now());}catch(java.text.ParseException|IllegalArgumentException ex){c.fail(c.t("Invalid duration","時間を確認してください"),ex);return;}clock.setText(FOCUS.display(now()));});button(actions,c.t("Pause / resume","一時停止／再開"),()->{FOCUS.toggle(now());clock.setText(FOCUS.display(now()));});button(actions,c.t("Reset","リセット"),()->{FOCUS.reset();clock.setText("00:00");});p.add(actions);p.add(Ui.muted(c.t("1–180 minutes · independent of Minecraft","1〜180分 · Minecraftとは独立して動作")));return p;}
    private JPanel notes(){var p=panel();p.add(Ui.title(c.t("Keep a thought for later","あとで見返したいメモ")));JTextArea text=new JTextArea(Instance.config(c.settings.instance()).deskNotes,12,40);text.setLineWrap(true);text.setWrapStyleWord(true);JScrollPane scroll=new JScrollPane(text);p.add(Box.createVerticalStrut(16));p.add(scroll);JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.setOpaque(false);button(actions,c.t("Save note","メモ保存"),()->{if(text.getText().length()>1400){c.fail(c.t("Note too long","メモが長すぎます"),new IllegalArgumentException("1400 characters maximum"));return;}persist(cfg->cfg.deskNotes=text.getText());});button(actions,c.t("Copy","コピー"),()->copy(text.getText()));p.add(actions);p.add(Ui.muted(c.t("Shared with the in-game tool desk · 1400 characters","ゲーム内のツールデスクと共有 · 1400文字まで")));return p;}
    private JPanel calculator(){var p=panel();p.add(Ui.title(c.t("Coins, crafting and everyday math","コイン・クラフト・日常の計算")));JTextField input=new JTextField("1.5m * 3 + 200k");input.setMaximumSize(new Dimension(Integer.MAX_VALUE,40));JLabel result=Ui.title("");p.add(Box.createVerticalStrut(20));p.add(input);p.add(Box.createVerticalStrut(20));p.add(result);JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.setOpaque(false);Runnable calculate=()->{try{result.setText(String.format(java.util.Locale.ROOT,"%,.4f",Calc.eval(input.getText())));}catch(IllegalArgumentException ex){result.setText(c.t("Check the expression","数式を確認してください"));}};button(actions,c.t("Calculate","計算"),calculate);input.addActionListener(e->calculate.run());button(actions,c.t("Copy result","結果をコピー"),()->copy(result.getText()));p.add(actions);p.add(Ui.muted("+ − × ÷ ^ ( )  ·  k / m / b / t"));return p;}
    private JPanel random(){var p=panel();p.add(Ui.title(c.t("Let chance choose","たまには運に任せよう")));JTextField choices=new JTextField(c.t("Mining, Fishing, Farming","採掘, 釣り, 農業"));choices.setMaximumSize(new Dimension(Integer.MAX_VALUE,40));p.add(Box.createVerticalStrut(20));p.add(choices);JLabel result=Ui.label("?",32,Font.BOLD,Theme.ACCENT);p.add(Box.createVerticalStrut(20));p.add(result);JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.setOpaque(false);button(actions,c.t("Pick one","ひとつ選ぶ"),()->{var entries=java.util.Arrays.stream(choices.getText().split("[,、]",-1)).map(String::strip).filter(s->!s.isEmpty()).toList();result.setText(entries.isEmpty()?c.t("Add some choices","候補を入力してください"):entries.get(ThreadLocalRandom.current().nextInt(entries.size())));});button(actions,c.t("Coin flip","コイントス"),()->result.setText(ThreadLocalRandom.current().nextBoolean()?c.t("Heads","表"):c.t("Tails","裏")));for(int sides:new int[]{6,20})button(actions,"D"+sides,()->result.setText(Integer.toString(ThreadLocalRandom.current().nextInt(1,sides+1))));p.add(actions);return p;}
    private JPanel tasks(){var p=panel();p.add(Ui.title(c.t("One small step at a time","ひとつずつ、前に進もう")));DefaultListModel<String> model=new DefaultListModel<>();JList<String> list=new JList<>(model);Runnable refresh=()->{model.clear();for(var item:Instance.config(c.settings.instance()).todos)model.addElement((item.done?"✓ ":"□ ")+item.text);};refreshTasks=refresh;refresh.run();p.add(Box.createVerticalStrut(16));p.add(new JScrollPane(list));JTextField task=new JTextField();task.putClientProperty("JTextField.placeholderText",c.t("New task (up to 80 characters)","新しいToDo（80文字まで）"));task.setMaximumSize(new Dimension(Integer.MAX_VALUE,38));p.add(task);JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.setOpaque(false);button(actions,c.t("Add","追加"),()->{String text=task.getText().strip();if(text.isEmpty()||text.length()>80){c.fail(c.t("Invalid task","ToDoを確認してください"),new IllegalArgumentException(c.t("Use 1–80 characters","1〜80文字で入力してください")));return;}if(persist(cfg->{if(cfg.todos.size()>=30)throw new IllegalArgumentException(c.t("Maximum 30 tasks","ToDoは30件までです"));cfg.todos.add(new SkyPilotConfig.Todo(text));})){refresh.run();task.setText("");}});button(actions,c.t("Toggle complete","完了を切り替え"),()->{int index=list.getSelectedIndex();String displayed=list.getSelectedValue();if(index>=0)persist(cfg->{if(index>=cfg.todos.size()||!cfg.todos.get(index).text.equals(displayed.substring(2)))throw new IllegalStateException(c.t("The task list changed. Select the task again.","ToDo一覧が更新されました。もう一度選択してください。"));cfg.todos.get(index).done=!cfg.todos.get(index).done;});refresh.run();});button(actions,c.t("Clear completed","完了分を削除"),()->{persist(cfg->cfg.todos.removeIf(item->item.done));refresh.run();});p.add(actions);return p;}
    private JPanel arcade(){var p=panel();p.add(score);p.add(Box.createVerticalStrut(12));board.setOpaque(false);board.setMaximumSize(new Dimension(320,320));board.setMinimumSize(new Dimension(320,320));board.setPreferredSize(new Dimension(320,320));for(int i=0;i<16;i++){tiles[i]=new JLabel("",SwingConstants.CENTER);tiles[i].setOpaque(true);tiles[i].setFont(Theme.font(Font.BOLD,24));board.add(tiles[i]);}p.add(board);JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.setOpaque(false);String[] labels={"←","→","↑","↓"},keys={"LEFT","RIGHT","UP","DOWN"};for(int i=0;i<4;i++){int d=i;button(actions,labels[i],()->move(d));p.getInputMap(JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT).put(KeyStroke.getKeyStroke(keys[i]),keys[i]);p.getActionMap().put(keys[i],new AbstractAction(){public void actionPerformed(ActionEvent e){move(d);}});}button(actions,c.t("Undo","一手戻す"),()->{game.undo();drawBoard();});button(actions,c.t("New game","新しく遊ぶ"),()->{game.restart();drawBoard();});p.add(actions);p.add(Ui.muted(c.t("Arrow keys or buttons · merge equal tiles","矢印キーまたはボタン · 同じ数字を合体")));drawBoard();return p;}
    private void move(int d){game.move(d);drawBoard();}
    private void drawBoard(){int[] values=game.cells();for(int i=0;i<16;i++){int value=values[i];tiles[i].setText(value==0?"":Integer.toString(value));tiles[i].setForeground(Theme.TEXT);tiles[i].setBackground(value==0?Theme.SURFACE_2:Theme.mix(Theme.SURFACE_2,Theme.ACCENT,Math.min(.85,.20+Math.log(value)/Math.log(2)*.07)));}score.setText("2048  ·  "+c.t("Score ","スコア ")+game.score()+(game.over()?c.t(" · Game over"," · 終了"):""));}
    private void copy(String text){try{Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text),null);c.ok(c.t("Copied","コピーしました"),"");}catch(Exception ex){c.fail(c.t("Clipboard unavailable","クリップボードを利用できません"),ex);}}
    private void button(JPanel p,String label,Runnable action){JButton b=Widgets.button(label,null);b.addActionListener(e->action.run());p.add(b);}
    JComponent view(){return root;}
}
